from fastapi import APIRouter

from app.agent import gemini_client
from app.core import store
from app.models.anomaly import Checklist, ChecklistAgentPlan

router = APIRouter(prefix="/agent", tags=["agent"])


@router.get("/checklist", response_model=Checklist)
def checklist():
    open_items = store.list_anomalies(status="open")
    return gemini_client.build_checklist(open_items)


@router.get("/plan", response_model=ChecklistAgentPlan)
def agent_plan(use_gemini: bool = True):
    """Returns the typed structured audit plan generated by Gemini (Feature C4)."""
    open_items = store.list_anomalies(status="open")
    return gemini_client.generate_agent_plan(open_items, use_llm=use_gemini)


@router.get("/verify")
def verify_agent():
    return gemini_client.verify_gemini_connection()

